            q_next = 52  # 0x34
        else:
            q_next = d_state

        # Return concrete unsigned 8-bit output after the negedge has settled.
        outputs.append({"q": q_next & 0xFF})

        # Mid changes happen AFTER sampling and are carried to the next row start.
        if "mid" in row:
            mid = row["mid"]
            if mid:
                if "d" in mid:
                    d_state = mid["d"]
